      pas:[{t:'Placement en Grande-Bretagne.', g:'W_{f} = W_{0} × (1 + r_{GBP})', n:'W_{f} = 1 000 000 × (1 + 0,06)', r:'W_{f} = 1 060 000 #t{ GBP}'},
           {t:'Placement couvert aux États-Unis : comptant, placement, revente à terme.', g:'W_{f} = #f{W_{0}}{S} × (1 + r_{USD}) × f', n:'W_{f} = #f{1 000 000}{0,68} × (1 + 0,04) × 0,6874', r:'W_{f} ≈ 1 051 317,65 #t{ GBP}'}],
