      pas:[{t:'Placement aux États-Unis.', g:'W_{f} = W_{0} × (1 + r_{USD})', n:'W_{f} = 1 000 000 × (1 + 0,04)', r:'W_{f} = 1 040 000 #t{ USD}'},
           {t:'Placement couvert en Grande-Bretagne.', g:'W_{f} = #f{W_{0} × S × (1 + r_{GBP})}{f}', n:'W_{f} = #f{1 000 000 × 0,68 × (1 + 0,06)}{0,6874}', r:'W_{f} ≈ 1 048 588,89 #t{ USD}'}],
